parse_as_infix("dqip_ipow",(24,"right"));;

let dqip_power = new_definition
  `(base:int) dqip_ipow (exponent:int) =
     base pow (if exponent < (&0:int) then 0 else num_of_int exponent)`;;

let dqip_value = new_definition
  `dqip_value
     (pelts:'p->int->int64) (offset:'p->int) (p:'p) (n:int) =
     if n <= (&0:int) then (&0:int)
     else
       isum (0..num_of_int n - 1)
         (\k. dqip_radix pow k * dqip_u64 (pelts p (offset p + &k)))`;;

let dqip_valid = new_definition
  `dqip_valid
     (data_length:'p->num)
     (offset:'p->int)
     (minimum:'p->int)
     (maximum:'p->int)
     (p:'p) (n:int) <=>
     dqip_int32_in_bounds n /\
     (&0:int) <= n /\
     (&0:int) <= minimum p /\
     minimum p <= offset p /\
     offset p + n <= maximum p /\
     maximum p <= &(data_length p)`;;

let dqip_map_eq_sub_shift = new_definition
  `dqip_map_eq_sub_shift
     (left:int->int64) (right:int->int64)
